UPDATE mac_user
SET user_pid = #{pid}, user_pid_2 = #{pid2}, user_pid_3 = #{pid3}
WHERE user_id = #{userId} AND user_pid = 0

UPDATE mac_user
SET user_random = #{random}
WHERE user_id = #{userId} AND user_random = #{oldRandom}

UPDATE mac_user
SET user_qq = #{qq}, user_question = #{question}, user_answer = #{answer}
, user_nick_name = #{nickName}
, user_pwd = #{pwd}, user_random = #{random}
WHERE user_id = #{userId} AND user_pwd = #{oldPwd}

UPDATE mac_user
SET user_pwd = #{pwd}, user_random = #{random}
WHERE user_id = #{userId} AND user_name = #{name} AND user_question = #{question} AND user_answer = #{answer}

UPDATE mac_user
SET user_portrait = #{portrait}
WHERE user_id = #{userId}

UPDATE mac_user
SET group_id = 2
WHERE user_id = #{userId} AND user_status = 1 AND group_id > 2 AND user_end_time < #{now}
